import Foundation
import CryptoKit
import XCTest
@testable import ProjectAgentCompanion

final class ProjectSharingCryptoTests: XCTestCase {
    // Generated by Node's P-256 ECDH / HKDF / AES-GCM implementation. This
    // catches accidental divergence between the Mac grant and iPhone reader.
    private let recipientPrivateKey = "NF_-4aJ-OgAU-VcnscLf8cVTw1G-wYjiIV84CgQjlRM"
    private let wrapped = #"{"version":1,"algorithm":"P256-HKDF-SHA256-A256GCM","senderPublicKey":"MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAElkYMrGyUYdnR+Zqt1ONrGEcFYZufwMUYC5ZmS1M/tGHvWzdMhpYrYaHOB7xL0aBf262YwfstDmFbDQdeKZOMqg==","salt":"BwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwc=","nonce":"CQkJCQkJCQkJCQkJ","ciphertext":"zPFnpEWHCqwVty/X9B1GCz+v7BWH/RvI4vnf3EdHmPmUNKyrX03ivHODcw==","tag":"8Hr4c4jsirZkiILqnOwhtw=="}"#

    private var privateKeyData: Data {
        var encoded = recipientPrivateKey.replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        encoded += String(repeating: "=", count: (4 - encoded.count % 4) % 4)
        return Data(base64Encoded: encoded)!
    }

    func testOpensMacProjectGrant() throws {
        let key = try AccountDeviceGrant.openProjectKey(
            wrapped, grantID: "grant-test", projectID: "project-test",
            deviceID: "device-test", keyEpoch: 3, privateKeyData: privateKeyData
        )
        XCTAssertEqual(key, "BQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQU")
    }

    func testGrantCannotBeReusedForAnotherProject() {
        XCTAssertThrowsError(try AccountDeviceGrant.openProjectKey(
            wrapped, grantID: "grant-test", projectID: "other-project",
            deviceID: "device-test", keyEpoch: 3, privateKeyData: privateKeyData
        ))
    }

    func testVerifiedSharedFileCacheIsProjectScopedAndClearedOnLeave() throws {
        let userID = UUID().uuidString
        let projectID = UUID().uuidString
        let otherProjectID = UUID().uuidString
        let bytes = Data("shared proof".utf8)
        let sha256 = Data(SHA256.hash(data: bytes))
            .map { String(format: "%02x", $0) }.joined()
        defer { MobileProjectSharingCache.clear(userID: userID) }
        let first = try MobileProjectSharingCache.saveVerifiedFile(
            bytes, filename: "proof.txt", attachmentID: "attachment-one",
            userID: userID, projectID: projectID, epoch: 1
        )
        let second = try MobileProjectSharingCache.saveVerifiedFile(
            bytes, filename: "proof.txt", attachmentID: "attachment-two",
            userID: userID, projectID: otherProjectID, epoch: 1
        )
        XCTAssertEqual(MobileProjectSharingCache.verifiedFile(
            filename: "proof.txt", attachmentID: "attachment-one", userID: userID,
            projectID: projectID, epoch: 1, size: bytes.count, sha256: sha256
        ), first)
        XCTAssertNil(MobileProjectSharingCache.verifiedFile(
            filename: "proof.txt", attachmentID: "attachment-one", userID: userID,
            projectID: projectID, epoch: 1, size: bytes.count, sha256: String(repeating: "0", count: 64)
        ))
        MobileProjectSharingCache.clearProject(userID: userID, projectID: projectID)
        XCTAssertFalse(FileManager.default.fileExists(atPath: first.path))
        XCTAssertTrue(FileManager.default.fileExists(atPath: second.path))
    }
}
